from z3 import *

def solve_latin_square(grid):
    solver = Solver()
    n = 8
    # Create a 8x8 matrix of variables
    x = [[Int(f"x_{i}_{j}") for j in range(n)] for i in range(n)]

    # Add constraints: each cell is between 0 and 7
    for i in range(n):
        for j in range(n):
            solver.add(x[i][j] >= 0, x[i][j] < n)

    # Add constraints: each row contains each value exactly once
    for i in range(n):
        solver.add(Distinct([x[i][j] for j in range(n)]))

    # Add constraints: each column contains each value exactly once
    for j in range(n):
        solver.add(Distinct([x[i][j] for i in range(n)]))

    # Add pre-filled clues
    for i in range(n):
        for j in range(n):
            if grid[i * n + j] != -1:
                solver.add(x[i][j] == grid[i * n + j])

    if solver.check() == sat:
        model = solver.model()
        result = []
        for i in range(n):
            for j in range(n):
                result.append(model.evaluate(x[i][j]).as_long())
        return result
    else:
        return None

